from jsonb_to_recordset('[{"clave":"CU:SEM:cu-espana-smeta-search:smeta-compra-nombres-de-competidores","marca":"CU","tipo":"SEM","campana":"CU España - Smeta - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Negativos de competidores y exacta — SMETA compra nombres de competidores","detalle":"intertek, tüv, dnv, veolia, sgs, bureau veritas, aenor a negativo. «smeta auditoria» a exacta. Sumar [smeta], [sedex], [auditoria smeta].\n\nPain point: De ARS 832 a ARS 4.095 por día. El 80% del gasto visible son Intertek, TÜV SÜD, DNV, Veolia, «cuadro comparativo iso 9001 14001 45001». Entra por «smeta auditoria» en frase.","evidencia":{"unidad":"España","estado_en_plan":"Nuevo"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-espana-caes-search:caes-sigue-comprando-certificados-de-vivienda","marca":"CU","tipo":"SEM","campana":"CU España - CAEs - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Aplicar el Anexo A — CAEs sigue comprando certificados de vivienda","detalle":"vivienda, particular, gratis, ce3x, certicalia, online a negativo. Amplia a frase. Exactas [sistema CAE], [verificación de actuaciones CAE].\n\nPain point: ARS 2.441 por día. Ninguno de los seis negativos propuestos está aplicado; la amplia sigue en amplia.","evidencia":{"unidad":"España","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-espana-ifs-search:ifs-genericos-y-sin-exactas","marca":"CU","tipo":"SEM","campana":"CU España - IFS - SEARCH","grupo":null,"sitio":null,"pagina":null,"titulo":"Nombrar la norma — IFS: genéricos y sin exactas","detalle":"[ifs food], [certificado ifs], [norma ifs]. Grupos ISO 22000 y FSSC 22000. servsafe, manipulación, food handler a negativo.\n\nPain point: ARS 2.355 por día con las mismas 9 keywords. Solo «curso» está en negativos.","evidencia":{"unidad":"España","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-espana-textile-search:textile-paga-oeko-tex-y-forestal-compra-sostenibilidad","marca":"CU","tipo":"SEM","campana":"CU España - Textile - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Negativos, exacta y grupo FSC — Textile paga OEKO-TEX y Forestal compra «sostenibilidad»","detalle":"oeko tex, organic cotton standard a negativo en Textile. En Forestal: «pefc certification» a exacta, sostenibilidad y pymes a negativo, grupo FSC con su página.\n\nPain point: oeko tex sigue sin ser negativo. En Forestal (ARS 3.243 por día, el doble) la keyword «pefc certification» trae «sostenibilidad» a secas: ARS 6.284 en 13 días. Sigue sin grupo FSC.","evidencia":{"unidad":"España","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-espana-gmp-search:gmp-empezo-a-gastar-sin-reconstruirse","marca":"CU","tipo":"SEM","campana":"CU España - GMP+ - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Reconstruir sobre lo que se busca — GMP+ empezó a gastar sin reconstruirse","detalle":"[gmp+], [gmp plus], [feed safety], [certificacion gmp]. Pausar el resto.\n\nPain point: ARS 595 por día con las 31 keywords originales, 2 clics. Orgánico: 5.031 búsquedas en posición 13,7.","evidencia":{"unidad":"España","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:espana:iso-45001-la-mayor-demanda-sigue-sin-campana","marca":"CU","tipo":"SEM","campana":null,"grupo":null,"sitio":null,"pagina":null,"titulo":"Campaña ISO 45001 — ISO 45001, la mayor demanda, sigue sin campaña","detalle":"Sobre la página existente, en exacta, con el modelo de la de ISO 27001 que ya convierte.\n\nPain point: 72.363 búsquedas orgánicas con página propia. En seis semanas se abrieron seis campañas en Argentina y ninguna acá.","evidencia":{"unidad":"España","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-portugal-plasticos-search:plasticos-sigue-pagando-recyclass-que-rankea-3o","marca":"CU","tipo":"SEM","campana":"CU Portugal - Plasticos - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Exacta con tope, 30 días — Plásticos sigue pagando recyclass, que rankea 3º","detalle":"recyclass a exacta con CPC máximo bajo. Si el clic orgánico compensa, pausar.\n\nPain point: ARS 2.554 por día, cuatro veces la auditoría. La posición orgánica no cambió.","evidencia":{"unidad":"Portugal","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-portugal-gmp-search:fsc-entra-por-pefc-gmp-vacia-biomasa-desperto","marca":"CU","tipo":"SEM","campana":"CU Portugal - GMP+ - SEARCH","grupo":null,"sitio":null,"pagina":null,"titulo":"Grupo FSC · GMP+ rehecha · revisar Biomasa — FSC entra por PEFC · GMP+ vacía · Biomasa despertó","detalle":"Grupo FSC con landing propia. GMP+ con [gmp+], [gmp plus]. Biomasa: mirar términos antes de que se consolide.\n\nPain point: Sin grupo FSC. GMP+ con 24 keywords y cero gasto. Biomasa pasó de ARS 16 a ARS 1.324 por día con 6 clics.","evidencia":{"unidad":"Portugal","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-portugal-textile-search:textile-bien-con-ruido-nuevo","marca":"CU","tipo":"SEM","campana":"CU Portugal - Textile - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Negativos chicos — Textile: bien, con ruido nuevo","detalle":"ppwr, wordly, database a negativo. Exactas [gots], [gots certification], [grs portugal].\n\nPain point: ARS 3.795 por día, 89% del gasto con anuncio fuerte o parcial. «ppwr» y «wordly» entran por GRS e Higg.","evidencia":{"unidad":"Portugal","estado_en_plan":"Nuevo"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-canada-aqua-fisheries-search:forestry-y-aqua-siguen-activas","marca":"CU","tipo":"SEM","campana":"CU Canada- Aqua / Fisheries - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Pausar — Forestry y Aqua siguen activas","detalle":"Pausar las dos. El presupuesto va a TEMO ({n(s7[''temo_na''][''impresiones''])} búsquedas orgánicas, sin campaña) y a CanadaGAP limpia.\n\nPain point: Forestry ARS 5.788 por día (+22%), Aqua ARS 1.867 (×2,3). El sitio sigue sin contenido forestal ni acuícola para Canadá.","evidencia":{"unidad":"Canadá","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-canada-canada-gap-search:canadagap-y-globalg-a-p-sin-los-negativos","marca":"CU","tipo":"SEM","campana":"CU Canada - Canada Gap - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Aplicar y acotar — CanadaGAP y GLOBALG.A.P. sin los negativos","detalle":"supply chain management, indocert, consultant, cargill a negativo. Exactas [canada gap], [canadagap], [global gap certification].\n\nPain point: CanadaGAP ARS 2.485 por día, ninguno de los cuatro negativos aplicado. GLOBALG.A.P. se quintuplicó a ARS 1.991.","evidencia":{"unidad":"Canadá","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-canada-cannabis-search:cannabis-se-retiro-cumcs-rankea-2o-sin-campana","marca":"CU","tipo":"SEM","campana":"CU Canada - Cannabis - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Campaña de defensa cumcs — Cannabis se retiró; cumcs rankea 2º sin campaña","detalle":"Grupo chico en exacta sobre la página del estándar, con la landing UTM que ya existía.\n\nPain point: La campaña de Cannabis fue eliminada. Orgánicamente «cumcs» tiene 1.107 búsquedas en posición 1,9.","evidencia":{"unidad":"Canadá","estado_en_plan":"Nuevo"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-united-states-organic-usda-nop-search:usda-nop-el-triple-en-busquedas-de-definicion","marca":"CU","tipo":"SEM","campana":"CU United States - Organic - USDA NOP - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Negativos de definición y tope — USDA NOP: el triple, en búsquedas de definición","detalle":"what is, what does, mean, meaning, how to become a negativo. omri, organic chicken, organic land también. CPC máximo. Exactas [certified organic], [national organic program].\n\nPain point: «what does certified organic mean» ARS 18.726 por 2 clics; «what is certified organic», «how to get certified as organic». Ninguno de los tres negativos propuestos aplicado. Cero conversiones.","evidencia":{"unidad":"Estados Unidos","estado_en_plan":"Nuevo"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-united-states-organic-primusgfs-search:primusgfs-sin-gasto-con-la-exacta-puesta","marca":"CU","tipo":"SEM","campana":"CU United States - Organic - PrimusGFS - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Verificar por qué no publica — PrimusGFS: sin gasto, con la exacta puesta","detalle":"Revisar estado de las keywords y del anuncio. Negativo consultant, consultoría, advisor a nivel cuenta: sigue sin estar.\n\nPain point: Se sumó [primusgfs]. El presupuesto de ARS 8.000 por día no se está usando: 28 keywords activas, cero impresiones con gasto.","evidencia":{"unidad":"Estados Unidos","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:argentina:eudr-funciona-con-dos-terminos-que-no-son-cliente","marca":"CU","tipo":"SEM","campana":null,"grupo":null,"sitio":null,"pagina":null,"titulo":"Negativos de definición — EUDR: funciona, con dos términos que no son cliente","detalle":"que significa, que es, resumen, pdf a negativo. Mantener las exactas de soja, cacao, madera. Sumar [certificacion eudr argentina].\n\nPain point: ARS 3.409 por día, 27 clics. «eudr que significa» ARS 5.493 por un clic; Google marca una keyword «por debajo» en relevancia.","evidencia":{"unidad":"Argentina","estado_en_plan":"Nuevo"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-argentina-ghg-search:ghg-compra-creditos-de-carbono","marca":"CU","tipo":"SEM","campana":"CU Argentina - GHG - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Sacar la keyword — GHG compra «creditos de carbono»","detalle":"Eliminar [creditos de carbono]. Negativos bonos, mercado, precio, valor. Mantener verificación ISO 14064 e inventario GEI.\n\nPain point: Misma keyword que lleva a Peterson a comprar el mercado de bonos. Ya trajo «valor de bonos de carbono». Control Union verifica, no vende créditos.","evidencia":{"unidad":"Argentina","estado_en_plan":"Nuevo"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-argentina-biocombustible-search:biocombustible-keywords-iscc-anuncio-2bsvs","marca":"CU","tipo":"SEM","campana":"CU Argentina - Biocombustible - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Un grupo por esquema — Biocombustible: keywords ISCC, anuncio 2BSvs","detalle":"Grupo ISCC con anuncio y landing ISCC; grupo 2BSvs con los suyos. Definir antes el corte con Peterson, que compra Bioenergía.\n\nPain point: Las 26 keywords dicen ISCC; los anuncios dicen «2BSvs, alternativa a ISCC EU». Todavía sin gasto. Cuando publique, va a cobrar clics de gente que busca ISCC y ve otro esquema.","evidencia":{"unidad":"Argentina","estado_en_plan":"Decisión"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-argentina-cadena-de-custodia-search:cadena-de-custodia-y-agro-sostenible-no-publican","marca":"CU","tipo":"SEM","campana":"CU Argentina - Cadena de Custodia - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Ampliar y alinear — Cadena de custodia y Agro sostenible no publican","detalle":"FSC: [certificacion fsc], [fsc argentina], [cadena de custodia fsc]. Agro: keywords FSA o anuncio RTRS, no uno de cada.\n\nPain point: Una keyword activa cada una (FSC, RTRS) y cero gasto en 13 días. Agro sostenible anuncia FSA con keyword RTRS.","evidencia":{"unidad":"Argentina","estado_en_plan":"Nuevo"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:argentina:smeta-argentina-ya-existe-era-la-mejora-no5","marca":"CU","tipo":"SEM","campana":null,"grupo":null,"sitio":null,"pagina":null,"titulo":"Mantener y separar — SMETA Argentina ya existe: era la mejora nº5","detalle":"Campaña propia SMETA con presupuesto propio; hoy comparte ARS 2.000 por día con FSSC.\n\nPain point: Grupos SMETA compra y proceso dentro de Industria, ARS 371 por día, anuncio fuerte. Orgánico: 8.890 búsquedas, ×19 interanual.","evidencia":{"unidad":"Argentina","estado_en_plan":"Hecho"},"prioridad":"media","estado":"hecha","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"PCU:SEM:espana-y-argentina:se-llama-pcu-y-ninguna-marca-certifica-asi","marca":"PCU","tipo":"SEM","campana":null,"grupo":null,"sitio":null,"pagina":null,"titulo":"Definir la marca y renombrar — Se llama «PCU» y ninguna marca certifica así","detalle":"Campañas y anuncios como Control Union, con landing en controlunion.com. Si se quiere que Peterson venda preparación para certificar, va en campaña de Peterson con vocabulario de preparación, no de certificación.\n\nPain point: El manual no admite piezas ni campañas sin marca. ISO 27001 es certificación: la emite Control Union. Peterson no certifica. Un anuncio que dice «Peterson and Control Union» compite consigo mismo en la búsqueda.","evidencia":{"unidad":"España y Argentina","estado_en_plan":"Decisión"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"PCU:SEM:pcu-tech-iso-27001-search:la-exacta-iso-27001-sigue-sin-existir","marca":"PCU","tipo":"SEM","campana":"PCU Tech - ISO 27001 - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Exactas y control de CPC — La exacta [iso 27001] sigue sin existir","detalle":"[iso 27001], [iso27001], [norma iso 27001], [iso iec 27001] en exacta con CPC máximo. Baja el costo del término que ya se paga.\n\nPain point: «iso 27001» a secas costó ARS 73.169 en España y ARS 56.643 en Argentina en 13 días, entrando por «certificacion iso 27001» en frase.","evidencia":{"unidad":"España y Argentina","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"PCU:SEM:espana-y-argentina:busquedas-informativas-a-ars-6-000-el-clic","marca":"PCU","tipo":"SEM","campana":null,"grupo":null,"sitio":null,"pagina":null,"titulo":"Negativos — Búsquedas informativas a ARS 6.000 el clic","detalle":"que dice, dominios, pdf, resumen, 2022 pdf, controles, «iso 27» a negativo.\n\nPain point: «que dice la iso 27001» ARS 7.286, «dominios iso 27001 2022» ARS 6.021, «iso 27» ARS 5.895: un clic cada una.","evidencia":{"unidad":"España y Argentina","estado_en_plan":"Nuevo"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"PCU:SEM:pcu-tech-competidores-iso-27001-search:competidores-espana-desperto-con-relevancia-baja","marca":"PCU","tipo":"SEM","campana":"PCU Tech - Competidores ISO 27001 - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Anuncio de comparación real o pausar — Competidores España despertó con relevancia baja","detalle":"Si se mantiene, el anuncio tiene que responder a la comparación. Si no, pausar: ARS 2.180 por día en clics que Google considera poco relevantes.\n\nPain point: ARS 2.180 por día por «bureau veritas iso 27001» y «aenor iso 27001»; Google marca las dos keywords «por debajo de la media». En Argentina, ARS 901.","evidencia":{"unidad":"España y Argentina","estado_en_plan":"Nuevo"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"PS:SEM:ps-argentina-suse-huella-de-agua-search:huella-de-agua-3-y-100-fuera-de-foco","marca":"PS","tipo":"SEM","campana":"PS Argentina - SuSe - Huella de agua - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Eliminar la keyword y negativos — Huella de agua: ×3 y 100% fuera de foco","detalle":"Eliminar «gestion del agua industrial». tratamiento, efluentes, calculadora, planta a negativo. Exactas [huella hidrica corporativa], [iso 14046].\n\nPain point: De ARS 844 a ARS 2.613 por día. Sigue «gestion del agua industrial» trayendo tratamiento de efluentes. Cero negativos en la campaña.","evidencia":{"unidad":"Argentina","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"PS:SEM:ps-argentina-bioenergia-biocombustibles-search:bioenergia-2-y-sigue-en-biogas","marca":"PS","tipo":"SEM","campana":"PS Argentina - Bioenergia / Biocombustibles - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Pausar las dos — Bioenergía: ×2 y sigue en biogás","detalle":"Pausar Bioenergía y CeSu. Si se rehace Bioenergía sobre ISCC y 2BSvs, antes definir el corte con Control Union Argentina, que acaba de abrir Biocombustible con las mismas keywords.\n\nPain point: ARS 2.943 por día; biogas, dosbio, bio gas: 47% del gasto con anuncio nulo. CeSu también empezó a gastar (ARS 447 por día) con 37 de 39 keywords que nadie busca.","evidencia":{"unidad":"Argentina","estado_en_plan":"Decisión"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"PS:SEM:ps-argentina-suso-agricultura-regenerativa-search:agricultura-regenerativa-y-huella-de-carbono-sin-cambios","marca":"PS","tipo":"SEM","campana":"PS Argentina - SuSo - Agricultura regenerativa- Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Aplicar el Anexo A — Agricultura regenerativa y Huella de carbono, sin cambios","detalle":"Sacar la amplia «agricultura regenerativa en argentina». Negativos de marcas del agro, agtech, bonos, mercado, créditos, carbono neutral. Amplias a frase. Exactas [consultoria ambiental], [iso 14064].\n\nPain point: Agricultura ARS 2.356 por día, Huella de carbono ARS 2.456. La amplia sigue, «bonos de carbono» sigue, cero negativos en Huella de carbono.","evidencia":{"unidad":"Argentina","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"PS:SEM:ps-argentina-suse-esg-reportes-search:esg-la-mas-sana-con-los-mismos-huecos","marca":"PS","tipo":"SEM","campana":"PS Argentina - SuSe - ESG / Reportes - Search","grupo":null,"sitio":null,"pagina":null,"titulo":"Completar negativos y exactas — ESG: la más sana, con los mismos huecos","detalle":"gri 403, gri 401 y el patrón gri + número a negativo. [csrd], [estandar gri], [consultora esg].\n\nPain point: ARS 1.982 por día. «que es» ya está en negativos; gri + número, no.","evidencia":{"unidad":"Argentina","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"PS:SEM:argentina:el-sitio-sigue-sin-existir-en-argentina","marca":"PS","tipo":"SEM","campana":null,"grupo":null,"sitio":null,"pagina":null,"titulo":"Páginas en español — El sitio sigue sin existir en Argentina","detalle":"Una página en español por servicio pagado. Hasta entonces, cada campaña compite sola.\n\nPain point: Argentina es el 9% de las impresiones orgánicas de la propiedad; casi toda la visibilidad está en páginas en inglés.","evidencia":{"unidad":"Argentina","estado_en_plan":"Pendiente"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Plan de mejoras unificado"},{"clave":"CU:SEM:cu-espana-caes-search:certificados-y-sistema-cae:anuncio","marca":"CU","tipo":"SEM","campana":"CU España - CAEs - Search","grupo":"Certificados y Sistema CAE","sitio":null,"pagina":null,"titulo":"Reescribir el anuncio de Certificados y Sistema CAE","detalle":"Siete títulos, fuerza «pobre». Ninguno dice «verificación de actuaciones» ni «sujeto obligado», que es lo que compra la campaña; el orgánico entra por «verificacion cae» y «verificador cae». La mitad del gasto viene de particulares que buscan el certificado de su vivienda: eso no se arregla con títulos sino con negativos.\n\nTítulos propuestos: Verificamos Actuaciones CAE | Verificador CAE Acreditado | Sistema CAE: Verificamos | Sujetos Obligados y Delegados | Certificados Ahorro Energético | Verificación CAE para Empresas | Control Union España | Solicita Verificación CAE | Auditoría Técnica de Ahorros | Verificamos, No Gestionamos\n\nDescripciones propuestas: Organismo verificador acreditado por ENAC. Verificamos actuaciones de ahorro energético. | Para sujetos obligados y delegados: verificación técnica de CAE con rigor y plazos claros. | Convierte tus ahorros energéticos en certificados verificados. Cuéntanos tu actuación. | No gestionamos ni tramitamos CAE de particulares: verificamos actuaciones de empresas.\n\nQuitar: Rigor Técnico en Cada Proyecto\n\nAplicar antes los negativos de vivienda. La cuarta descripción cierra la puerta al particular de forma explícita.","evidencia":{"gasto_ars":58838,"fuerza_actual":"POOR","titulos_hoy":7,"titulos_propuestos":10},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-espana-ifs-search:food-safety:anuncio","marca":"CU","tipo":"SEM","campana":"CU España - IFS - SEARCH","grupo":"Food Safety","sitio":null,"pagina":null,"titulo":"Reescribir el anuncio de Food Safety","detalle":"Los títulos hablan de «seguridad alimentaria» en genérico y ninguno nombra IFS, ISO 22000 ni FSSC, que es lo que la gente escribe (ifs food, iso 22000, brcgs). En orgánico entran por haccp, iso 22000 y «certificaciones de seguridad alimentaria». Sugerencia: partir en tres grupos, IFS, ISO 22000/FSSC y HACCP, cada uno con su anuncio.\n\nTítulos propuestos: Certificación IFS Food | Auditoría IFS Food Versión 8 | Certificamos ISO 22000 | Certificación FSSC 22000 | Certificación HACCP | Organismo Certificador | Control Union España | Certificamos Food Safety | Auditores IFS en España | Solicita Tu Auditoría IFS\n\nDescripciones propuestas: Certificamos IFS Food, ISO 22000 y FSSC 22000. Organismo de certificación acreditado. | Auditoría IFS Food v8 con equipo auditor local. Cuéntanos tu planta y coordinamos fechas. | Certificación de seguridad alimentaria reconocida por GFSI para fabricantes y envasadores. | Más de 100 años certificando. Presencia en más de 80 países.\n\nQuitar: Soporte técnico completo · Auditorías para empresas · Equipo técnico experto\n\nBRCGS no va en títulos: no hay demanda ni contenido (33 búsquedas orgánicas en el histórico).","evidencia":{"gasto_ars":37135,"fuerza_actual":"AVERAGE","titulos_hoy":9,"titulos_propuestos":10},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"}]'::jsonb) as x(clave text, marca text, tipo text, campana text, grupo text, sitio text, pagina text, titulo text, detalle text, evidencia jsonb, prioridad text, estado text, mes_alta text, origen text)
left join seo_sem.campanas c on c.nombre = x.campana left join seo_sem.grupos g on g.campana_id = c.id and g.nombre = x.grupo
on conflict (clave) do update set campana_id = excluded.campana_id, grupo_id = excluded.grupo_id, sitio = excluded.sitio, pagina = excluded.pagina, titulo = excluded.titulo, detalle = excluded.detalle, evidencia = excluded.evidencia, prioridad = excluded.prioridad, origen = excluded.origen;
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen)
select x.clave, x.marca, x.tipo, c.id, g.id, x.sitio, x.pagina, x.titulo, x.detalle, x.evidencia, x.prioridad, x.estado, x.mes_alta, x.origen
from jsonb_to_recordset('[{"clave":"CU:SEM:cu-espana-textile-search:gots:anuncio","marca":"CU","tipo":"SEM","campana":"CU España - Textile - Search","grupo":"GOTS","sitio":null,"pagina":null,"titulo":"Reescribir el anuncio de GOTS","detalle":"Fuerza «pobre». La descripción dice «Control Union acompaña marcas»: es vocabulario de Peterson; Control Union certifica. Lo que la gente escribe: certificado gots, sello gots, certified gots organic cotton; en orgánico, «gots en español» y «qué es gots». OEKO-TEX aparece por keyword, no por anuncio: va a negativo.\n\nTítulos propuestos: Certificación GOTS | Certificado GOTS Para Tu Marca | Sello GOTS: Algodón Orgánico | GOTS: Qué Es y Cómo Certificar | Auditoría GOTS en España | GOTS Global Organic Textile | Certificamos GOTS y OCS | Organismo Certificador Textil | Control Union España | Solicita Tu Certificación GOTS\n\nDescripciones propuestas: Certificamos GOTS: textiles orgánicos con trazabilidad desde la fibra hasta la prenda. | Organismo de certificación GOTS. Cuéntanos tu producto: alcance, pasos y plazos. | Auditoría GOTS con equipo local en España y red en más de 80 países. | También certificamos OCS y GRS: contenido orgánico y reciclado en una misma auditoría.\n\nQuitar: Prepara Tu Auditoría · Auditoría Independiente\n\n«Prepara tu auditoría» sugiere preparación, que es servicio de Peterson. Control Union certifica y audita.","evidencia":{"gasto_ars":49259,"fuerza_actual":"POOR","titulos_hoy":8,"titulos_propuestos":10},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-espana-textile-search:grs:anuncio","marca":"CU","tipo":"SEM","campana":"CU España - Textile - Search","grupo":"GRS","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de GRS","detalle":"Anuncio correcto en tema; la gente escribe «global recycled standard» y «grs textile exchange», y en orgánico «grs» a secas domina (7.658 búsquedas, posición 9). Falta nombrar a Textile Exchange, que es como muchos identifican la norma.\n\nTítulos propuestos: Certificación GRS | GRS de Textile Exchange | Global Recycled Standard | Certificado GRS Reciclado | Auditoría GRS en España | Certificamos GRS y RCS | Reciclado Certificado GRS | Organismo Certificador Textil | Control Union España | Solicita Tu Certificación GRS\n\nDescripciones propuestas: Certificamos GRS y RCS, los estándares de contenido reciclado de Textile Exchange. | Auditoría GRS con equipo local. Trazabilidad del reciclado en toda la cadena textil. | Cuéntanos tu producto y te confirmamos alcance, requisitos y plazos de certificación. | Más de 100 años certificando. Red propia en más de 80 países.\n\nQuitar: grs textile certification · Prepara Tu Auditoría","evidencia":{"gasto_ars":32970,"fuerza_actual":"AVERAGE","titulos_hoy":8,"titulos_propuestos":10},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-espana-forestal-search:pefc:anuncio","marca":"CU","tipo":"SEM","campana":"CU España - Forestal - Search","grupo":"PEFC","sitio":null,"pagina":null,"titulo":"Reescribir el anuncio de PEFC","detalle":"Fuerza «pobre». Los términos son «pefc españa», «certificado madera pefc» y una porción creciente de «sostenibilidad» a secas por la keyword «pefc certification» en frase. FSC entra al grupo PEFC y ve un anuncio de PEFC: por eso el plan pide un grupo FSC propio, con este anuncio.\n\nTítulos propuestos: Certificación PEFC | Cadena de Custodia PEFC | Certificado PEFC de Madera | PEFC España: Certificamos | Auditoría PEFC Forestal | Certificación Forestal PEFC | Certificadora Forestal | Control Union España | Solicita Tu Certificación PEFC | Certificación PEFC y FSC\n\nDescripciones propuestas: Certificamos PEFC: cadena de custodia para madera, papel y productos forestales. | Auditoría PEFC con equipo local en España. Cuéntanos tu producto y coordinamos fechas. | Organismo de certificación forestal: PEFC y FSC en una misma auditoría. | Más de 100 años certificando. Presencia en más de 80 países.\n\nGrupo FSC nuevo con: «Certificación FSC», «Cadena de Custodia FSC», «Certificado FSC de Madera», «FSC España: Certificamos», landing en la página FSC.","evidencia":{"gasto_ars":55658,"fuerza_actual":"POOR","titulos_hoy":7,"titulos_propuestos":10},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-espana-smeta-search:social:anuncio","marca":"CU","tipo":"SEM","campana":"CU España - Smeta - Search","grupo":"Social","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de Social","detalle":"El anuncio está bien y el 80% del gasto reciente son nombres de competidores. No es un problema de anuncio: la keyword «smeta auditoria» en frase abrió la puerta. Cambio mínimo en el anuncio y negativos.\n\nTítulos propuestos: Auditoría SMETA | Auditoría SMETA 4 Pilares | SMETA 2 y 4 Pilares | Auditoría Social Sedex | SMETA España: Auditamos | Auditores SMETA Locales | Auditoría Ética y Laboral | Control Union España | Solicita Tu Auditoría SMETA | Certificación SMETA\n\nDescripciones propuestas: Auditoría SMETA 2 y 4 pilares para proveedores y cadenas de suministro. Equipo local. | Auditamos prácticas laborales, salud y seguridad, medio ambiente y ética de negocio. | Cuéntanos tu planta y tu cliente y coordinamos la auditoría SMETA en fecha. | Más de 100 años auditando. Red propia en más de 80 países.\n\nQuitar: Prepara Tu Auditoría\n\nNegativos: intertek, tüv, dnv, veolia, sgs, bureau veritas, aenor, kiwa. «smeta auditoria» a exacta.","evidencia":{"gasto_ars":61792,"fuerza_actual":"AVERAGE","titulos_hoy":7,"titulos_propuestos":10},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-espana-bioenergia-search:iscc:anuncio","marca":"CU","tipo":"SEM","campana":"CU España - Bioenergia - Search","grupo":"ISCC","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de ISCC","detalle":"Fuerza «pobre» con relación fuerte: la gente escribe «iscc», «iscc plus», «certificado iscc» y el anuncio lo dice. El problema es que la query «iscc» casi desapareció del orgánico (605 → 11 impresiones desde España): el anuncio hoy sostiene solo el tema. Faltan títulos de ISCC EU y de la directiva RED.\n\nTítulos propuestos: Certificación ISCC | ISCC EU e ISCC PLUS | Certificado ISCC Biomasa | Auditoría ISCC en España | Certificamos ISCC EU | Biocombustibles Certificados | Cumplimiento RED III | Organismo Certificador ISCC | Control Union España | Solicita Tu Certificación ISCC\n\nDescripciones propuestas: Certificamos ISCC EU e ISCC PLUS: biomasa, biocombustibles y materias primas sostenibles. | Auditoría ISCC con equipo local. Balance de masas y trazabilidad para RED III. | Cuéntanos tu materia prima y tu mercado y te confirmamos alcance y plazos. | Más de 100 años certificando. Presencia en más de 80 países.\n\nQuitar: Solicita Información","evidencia":{"gasto_ars":35369,"fuerza_actual":"POOR","titulos_hoy":7,"titulos_propuestos":10},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-espana-plasticos-search:recyclass:anuncio","marca":"CU","tipo":"SEM","campana":"CU España - Plasticos - Search","grupo":"RecyClass","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de RecyClass","detalle":"Relación fuerte: «recyclass» es el 98% del gasto. El orgánico muestra tres intenciones que el anuncio no nombra: reciclabilidad, contenido reciclado y reutilización de plásticos (830 búsquedas, posición 36).\n\nTítulos propuestos: Certificación RecyClass | RecyClass: Reciclabilidad | Reciclado Certificado | Auditoría RecyClass en España | Certificamos RecyClass | Plástico Reciclado Certificado | Trazabilidad del Reciclado | Organismo Certificador | Control Union España | Solicita Tu Certificación\n\nDescripciones propuestas: Certificamos RecyClass: reciclabilidad y contenido reciclado en envases plásticos. | Auditoría RecyClass con equipo local. Demuestra tu contenido reciclado sin greenwashing. | Cuéntanos tu producto y te confirmamos el esquema, el alcance y los plazos. | Más de 100 años certificando. Red propia en más de 80 países.\n\nQuitar: Prepara Tu Auditoría · Equipo Auditor Local","evidencia":{"gasto_ars":24841,"fuerza_actual":"AVERAGE","titulos_hoy":7,"titulos_propuestos":10},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-portugal-textile-search:gots:anuncio","marca":"CU","tipo":"SEM","campana":"CU Portugal - Textile - Search","grupo":"GOTS","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de GOTS","detalle":"La gente escribe «gots 8.0», «gots database», «gots symbol», «norma gots». El anuncio no nombra la versión ni el símbolo. La descripción «Apoio a marcas» es vocabulario de consultoría; Control Union certifica.\n\nTítulos propuestos: Certificação GOTS | Certificação GOTS 8.0 | Norma GOTS: Certificamos | Símbolo GOTS Para a Sua Marca | Auditoria GOTS em Portugal | GOTS Global Organic Textile | Certificamos GOTS e OCS | Organismo de Certificação | Control Union Portugal | Peça a Sua Certificação GOTS\n\nDescripciones propuestas: Certificamos GOTS 8.0: têxteis orgânicos com rastreabilidade da fibra ao produto final. | Auditoria GOTS com equipa local em Portugal e rede em mais de 80 países. | Diga-nos o seu produto e confirmamos âmbito, requisitos e prazos de certificação. | Também certificamos OCS e GRS: conteúdo orgânico e reciclado numa só auditoria.\n\nQuitar: Peça Informação","evidencia":{"gasto_ars":33149,"fuerza_actual":"AVERAGE","titulos_hoy":7,"titulos_propuestos":10},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-portugal-forestal-search:pefc:anuncio","marca":"CU","tipo":"SEM","campana":"CU Portugal - Forestal - Search","grupo":"PEFC","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de PEFC","detalle":"Relación fuerte, con «pefc o que é» entre los términos más caros: intención informativa. En orgánico, «pefc search» y «pefc certificate search»: la gente busca verificar certificados. Un título que responda «o que é» captura esa intención sin pagar por curiosidad pura.\n\nTítulos propuestos: Certificação PEFC | PEFC: O Que É e Como Obter | Cadeia de Custódia PEFC | Certificado PEFC de Madeira | Auditoria PEFC em Portugal | Certificação Florestal | Certificamos PEFC e FSC | Organismo de Certificação | Control Union Portugal | Peça a Sua Certificação PEFC\n\nDescripciones propuestas: Certificamos PEFC: cadeia de custódia para madeira, papel e produtos florestais. | Auditoria PEFC com equipa local em Portugal. Diga-nos o seu produto e marcamos datas. | Organismo de certificação florestal: PEFC e FSC numa só auditoria. | Mais de 100 anos a certificar. Presença em mais de 80 países.\n\nGrupo FSC próprio: «Certificação FSC», «Cadeia de Custódia FSC», «Madeira Certificada FSC», landing na página FSC.","evidencia":{"gasto_ars":52954,"fuerza_actual":"AVERAGE","titulos_hoy":7,"titulos_propuestos":10},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-portugal-plasticos-search:une-15343:anuncio","marca":"CU","tipo":"SEM","campana":"CU Portugal - Plasticos - Search","grupo":"UNE 15343","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de UNE 15343","detalle":"Los términos dicen «une en 15343 2008»: la gente cita la norma con año. Bien el anuncio, salvo «bso consulting» y «como reduzir a produção de resíduos», que son negativos, no títulos.\n\nTítulos propuestos: Certificação UNE-EN 15343:2008 | Plástico Reciclado Certificado | Auditoria EN 15343 | Rastreabilidade do Reciclado | Certificamos EN 15343 | Organismo de Certificação | Control Union Portugal | Peça a Sua Certificação\n\nDescripciones propuestas: Certificamos UNE-EN 15343:2008: rastreabilidade e conteúdo reciclado em plásticos. | Auditoria com equipa local em Portugal. Diga-nos o seu processo e confirmamos o âmbito. | Mais de 100 anos a certificar. Rede própria em mais de 80 países.\n\nQuitar: Cumprir EN 15343 · Peça Informação","evidencia":{"gasto_ars":13702,"fuerza_actual":"AVERAGE","titulos_hoy":7,"titulos_propuestos":8},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-portugal-biomasa-search:sure:anuncio","marca":"CU","tipo":"SEM","campana":"CU Portugal - Biomasa - Search","grupo":"SURE","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de SURE","detalle":"Un solo término, «certificado sur», con relación fuerte. En orgánico, «sure madeira» (60 búsquedas) y «sure sustainable resources». El anuncio no nombra madera ni RED III.\n\nTítulos propuestos: Certificação SURE | SURE Para Biomassa de Madeira | Certificado SURE: RED III | Auditoria SURE em Portugal | Certificamos SURE | Biomassa Sustentável: SURE | Organismo de Certificação | Control Union Portugal | Peça a Sua Certificação SURE\n\nDescripciones propuestas: Certificamos SURE: biomassa sólida e madeira com conformidade RED III e rastreabilidade. | Auditoria SURE com equipa local em Portugal. Diga-nos a sua cadeia e confirmamos âmbito. | Mais de 100 anos a certificar. Presença em mais de 80 países.\n\nQuitar: Peritos Em Bioenergia · Peça Informação","evidencia":{"gasto_ars":12083,"fuerza_actual":"AVERAGE","titulos_hoy":7,"titulos_propuestos":9},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-canada-forestry-search:fsc:anuncio","marca":"CU","tipo":"SEM","campana":"CU Canada - Forestry - Search","grupo":"FSC","sitio":null,"pagina":null,"titulo":"Reescribir el anuncio de FSC","detalle":"El grupo FSC usa el mismo anuncio genérico de «Forestry Certification». La gente escribe «fsc canada», «fsc chain of custody», «how to get fsc certification» y también en francés («normes fsc», ARS 8.498). Un anuncio FSC propio, y uno en francés si se mantiene la campaña. Vale solo si se decide no pausar Forestry.\n\nTítulos propuestos: FSC Certification Canada | FSC Chain of Custody Audit | How to Get FSC Certified | FSC Certified: We Certify | FSC Forest Management | Accredited Certification Body | FSC Auditors in Canada | Control Union Canada | Request FSC Certification | FSC and PEFC Certification\n\nDescripciones propuestas: We certify FSC chain of custody and forest management. Accredited certification body. | Tell us your products and markets and we confirm scope, requirements and timelines. | FSC audits with local auditors in Canada and a network in more than 80 countries. | Over 100 years of certification. 274+ offices and labs worldwide.\n\nVersión en francés: «Certification FSC Canada», «Chaîne de Contrôle FSC», «Organisme Certificateur FSC». Negativos de credencial personal siguen pendientes.","evidencia":{"gasto_ars":103110,"fuerza_actual":"GOOD","titulos_hoy":14,"titulos_propuestos":10},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-canada-canada-gap-search:canadagap-cert:anuncio","marca":"CU","tipo":"SEM","campana":"CU Canada - Canada Gap - Search","grupo":"CanadaGAP cert","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de CanadaGAP cert","detalle":"Relación fuerte en los términos correctos («canada gap», «canadagap certification», «canadagap 2026»). La descripción dice «CanadianGAP», nombre incorrecto del programa. Cargill, supply chain management e indocert son negativos, no anuncio.\n\nTítulos propuestos: CanadaGAP Certification | CanadaGAP Audit 2026 | Certified CanadaGAP Body | Fresh Produce Food Safety | CanadaGAP for Packers | CanadaGAP for Growers | Accredited Certification Body | Control Union Canada | Request CanadaGAP Audit | Greenhouse and Field Produce\n\nDescripciones propuestas: We certify CanadaGAP for growers, packers and repackers. Accredited certification body. | Book your CanadaGAP audit with local auditors. Tell us your operation and crop. | Food safety certification recognized by Canadian retailers and GFSI. | Over 100 years of certification. Presence in more than 80 countries.\n\nQuitar: Don''t Risk It, Get Certified · Packing House Support · Transparent and consistent","evidencia":{"gasto_ars":93875,"fuerza_actual":"GOOD","titulos_hoy":15,"titulos_propuestos":10},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-united-states-organic-usda-nop-search:switch-get-certified:anuncio","marca":"CU","tipo":"SEM","campana":"CU United States - Organic - USDA NOP - Search","grupo":"Switch & Get Certified","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de Switch & Get Certified","detalle":"Los términos más caros son definiciones («what does certified organic mean», «what is certified organic»): van a negativo, no a título. Lo que sí compra bien: «how to get certified organic», «organic certification», «national organic program». Falta nombrar el NOP y el ámbito (crop, livestock, handling).\n\nTítulos propuestos: USDA Organic Certification | Get USDA Organic Certified | NOP-Accredited Certifier | Organic Certification: Farms | Organic Handler Certification | Switch Your Organic Certifier | No Lapse When You Switch | Control Union USA | Request an Organic Quote | How to Get Certified Organic\n\nDescripciones propuestas: USDA NOP-accredited organic certifier for crops, handling and processing in the U.S. | Switch certifiers with no lapse in status. We manage the transfer for you. | Tell us your operation and we confirm scope, fees and timeline to certification. | Over 100 years of certification. Presence in more than 80 countries.\n\nQuitar: Named Contact, Every Time · CUC USA: 80+ Countries\n\n«organic chicken certification» (ARS 11.056): solo si el alcance incluye livestock; si no, negativo. Es un supuesto a confirmar con la unidad.","evidencia":{"gasto_ars":104379,"fuerza_actual":"AVERAGE","titulos_hoy":15,"titulos_propuestos":10},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-canada-globalg-a-p-search:globalg-a-p-cert:anuncio","marca":"CU","tipo":"SEM","campana":"CU Canada - GLOBALG.A.P. - Search","grupo":"GLOBALG.A.P cert","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de GLOBALG.A.P cert","detalle":"«global gap» sin punto es la forma en que la gente lo escribe (ARS 15.523) y ningún título lo dice así; «food safety consultant» es negativo. Títulos con «partner» y «support» suenan a consultoría.\n\nTítulos propuestos: GLOBALG.A.P. Certification | Global GAP Certification | GLOBALG.A.P. IFA Audit | GGAP Chain of Custody | Accredited Certification Body | GLOBALG.A.P. for Greenhouses | Control Union Canada | Request GLOBALG.A.P. Audit | Farm Certification Canada\n\nDescripciones propuestas: We certify GLOBALG.A.P. IFA and chain of custody. Accredited certification body. | Tell us your farm and crops and we confirm scope, requirements and audit dates. | Over 100 years of certification. Presence in more than 80 countries.\n\nQuitar: Farm Assurance Support · Don''t Risk It, Get Certified · Market Access Support · Improve Farm Compliance","evidencia":{"gasto_ars":22480,"fuerza_actual":"AVERAGE","titulos_hoy":15,"titulos_propuestos":9},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-argentina-agroexportacion-search:eudr-proceso:anuncio","marca":"CU","tipo":"SEM","campana":"CU Argentina - Agroexportación - Search","grupo":"EUDR proceso","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de EUDR proceso","detalle":"Campaña nueva y bien armada: relación fuerte, landing propia. «eudr que significa» (ARS 5.493, un clic) es definición: negativo. Falta un título que diga qué hace Control Union en EUDR con su verbo: verificar, no asesorar.\n\nTítulos propuestos: Verificación EUDR Argentina | Cumplimiento EUDR Verificado | Debida Diligencia EUDR | EUDR Soja, Carne y Madera | Libre de Deforestación | Auditores EUDR en Argentina | Organismo de Certificación | Control Union Argentina | Pedí Tu Verificación EUDR | EUDR: Aplica en Diciembre 2026\n\nDescripciones propuestas: Verificamos el cumplimiento EUDR: trazabilidad y debida diligencia para exportar a la UE. | Organismo de certificación con auditores en Argentina y red en más de 80 países. | Contanos tu producto y tu mercado y te confirmamos alcance, requisitos y plazos. | Más de 100 años certificando. Presencia en más de 80 países.\n\n«eudr que significa», «que es», «resumen» a negativo antes de cambiar el anuncio.","evidencia":{"gasto_ars":0,"fuerza_actual":"—","titulos_hoy":0,"titulos_propuestos":10},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEM:cu-argentina-biocombustible-search:iscc:anuncio","marca":"CU","tipo":"SEM","campana":"CU Argentina - Biocombustible - Search","grupo":"ISCC","sitio":null,"pagina":null,"titulo":"Grupo nuevo el anuncio de ISCC","detalle":"Las keywords dicen ISCC y el anuncio dice 2BSvs, «alternativa a ISCC EU». Cuando publique, cobrará clics de quien busca ISCC y ve otro esquema. Un grupo por esquema, cada uno con su anuncio y su landing.\n\nTítulos propuestos: Certificación ISCC Argentina | ISCC EU e ISCC PLUS | Certificamos ISCC EU | Biocombustibles a la UE | Auditoría ISCC en Argentina | Balance de Masas ISCC | Organismo Certificador ISCC | Control Union Argentina | Pedí Tu Certificación ISCC | Certificación ISCC y 2BSvs\n\nDescripciones propuestas: Certificamos ISCC EU e ISCC PLUS: biocombustibles, aceite y materias primas para la UE. | Auditoría ISCC con equipo local en Argentina. Balance de masas y trazabilidad RED III. | Contanos tu materia prima y tu mercado y te confirmamos alcance y plazos. | También certificamos 2BSvs. Te decimos cuál conviene según tu comprador.\n\nEl anuncio 2BSvs actual queda en su propio grupo con keywords 2BSvs. Antes: definir el corte con Peterson, que compra Bioenergía con las mismas keywords.","evidencia":{"gasto_ars":0,"fuerza_actual":"—","titulos_hoy":0,"titulos_propuestos":10},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"PCU:SEM:pcu-espana-iso-27001-search:compra:anuncio","marca":"PCU","tipo":"SEM","campana":"PCU España - ISO 27001 - Search","grupo":"Compra","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de Compra","detalle":"El anuncio ya usa las cifras y el verbo de Control Union («certificamos», «más de 100 años», «80 países», «274 oficinas»): es un anuncio de Control Union con nombre PCU. Relación fuerte. Faltan la versión 2022 y «ISO/IEC», que la gente escribe; «que dice», «dominios», «iso 27» son negativos.\n\nTítulos propuestos: Certificación ISO 27001 | ISO/IEC 27001:2022 | Certificamos ISO 27001 | Auditoría ISO 27001 en España | Certifica Tu SGSI | Certificadora ISO 27001 | Auditores ISO 27001 en España | Control Union España | Solicita Tu Presupuesto | Más de 100 Años Certificando\n\nDescripciones propuestas: Auditamos y certificamos ISO/IEC 27001:2022 con alcance acreditado. Solicita presupuesto. | Cuéntanos el alcance de tu SGSI y coordinamos la auditoría con el equipo local. | Entidad de certificación con más de 100 años y presencia en más de 80 países. | Certificación de seguridad de la información para empresas de cualquier tamaño.\n\nRenombrar campaña y anuncios como Control Union. Verificar el alcance acreditado para ISO 27001 antes de usar «acreditado» en títulos: es un supuesto.","evidencia":{"gasto_ars":149247,"fuerza_actual":"AVERAGE, AVERAGE","titulos_hoy":24,"titulos_propuestos":10},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"PCU:SEM:pcu-argentina-iso-27001:compra:anuncio","marca":"PCU","tipo":"SEM","campana":null,"grupo":null,"sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de Compra","detalle":"Mismo caso. En Argentina la gente escribe «iso iec 27001», «iso 27001 2022», «norma iso 27001» y «ciberseguridad»; el anuncio no nombra la versión ni ISO/IEC. Google califica la relevancia «media» en 14 de 15 keywords: hay margen.\n\nTítulos propuestos: Certificación ISO 27001 | Norma ISO/IEC 27001:2022 | Certificamos ISO 27001 | Auditoría ISO 27001 Argentina | Certificá Tu SGSI | Certificadora ISO 27001 | Seguridad de la Información | Control Union Argentina | Pedí Tu Cotización | Más de 100 Años Certificando\n\nDescripciones propuestas: Auditamos y certificamos ISO/IEC 27001:2022 con alcance acreditado. Pedí tu cotización. | Contanos el alcance de tu SGSI y coordinamos la auditoría con el equipo local. | Organismo de certificación con más de 100 años y presencia en más de 80 países. | Certificación de seguridad de la información: el certificado que piden tus clientes.","evidencia":{"gasto_ars":146405,"fuerza_actual":"AVERAGE, AVERAGE","titulos_hoy":24,"titulos_propuestos":10},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"PS:SEM:ps-argentina-suso-agricultura-regenerativa-search:regenerativa:anuncio","marca":"PS","tipo":"SEM","campana":"PS Argentina - SuSo - Agricultura regenerativa- Search","grupo":"Regenerativa","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de Regenerativa","detalle":"El anuncio está bien escrito; el gasto se va en tecnología agrícola, marcas del agro y pools de siembra, que ningún título puede responder: es la amplia. El tono puede ser más de Peterson: «nosotros», acompañar, co-desarrollar.\n\nTítulos propuestos: Agricultura Regenerativa | Transición Regenerativa | Programas Regenerativos Agro | Carbono en Suelo: Medimos | Te Acompañamos en Campo | Regenagri y Certificaciones | Consultoría Peterson | Diagnóstico y Monitoreo | Hablemos de Tu Campo | Impacto Medido en Campo\n\nDescripciones propuestas: Acompañamos a productores y empresas en la transición regenerativa, de punta a punta. | Co-desarrollamos programas regenerativos con datos de suelo, carbono e impacto. | Preparamos tu cadena para Regenagri y otras certificaciones. Hablemos de tu campo. | Para el mundo, para nosotros, para nuestras familias.\n\nQuitar: Monitoreo En Campo · Cadena Agricola · Impacto Agricola\n\nSacar la amplia primero: ningún título compensa 219 clics de marcas del agro.","evidencia":{"gasto_ars":68295,"fuerza_actual":"AVERAGE","titulos_hoy":14,"titulos_propuestos":10},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"PS:SEM:ps-argentina-suse-huella-de-carbono-gei-search:huella-carbono:anuncio","marca":"PS","tipo":"SEM","campana":"PS Argentina - SuSe - Huella de carbono / GEI - Search","grupo":"Huella carbono","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de Huella carbono","detalle":"Dos grupos con el mismo anuncio. La gente escribe «inventario gei argentina» (fuerte), «consultoria ambiental» y «como medir la huella de carbono de una empresa» (parcial): hay demanda de consultoría que es exactamente lo que Peterson vende y el anuncio no dice «consultora ambiental». Bonos, verra, carbono neutral son negativos.\n\nTítulos propuestos: Huella de Carbono Empresas | Consultora Ambiental | Inventario GEI Argentina | Medimos Tu Huella de Carbono | ISO 14064 e ISO 14067 | Alcances 1, 2 y 3 | Huella de Producto | Consultoría Peterson | Te Acompañamos a Medir | Hablemos de Tus Emisiones\n\nDescripciones propuestas: Medimos y gestionamos con vos la huella de carbono de tu empresa, tu producto y tu cadena. | Inventario GEI bajo ISO 14064 y GHG Protocol: alcances 1, 2 y 3 con datos sólidos. | Consultora ambiental con equipo en Argentina y presencia en más de 35 países. | Te preparamos para verificar tu inventario. Hablemos de tus emisiones.\n\nQuitar: AFOLU Agro · Carbono Corporativo · Reporte De Emisiones\n\nAplica a los dos grupos, Huella carbono y Huella producto.","evidencia":{"gasto_ars":29521,"fuerza_actual":"POOR","titulos_hoy":13,"titulos_propuestos":10},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"PS:SEM:ps-argentina-suse-esg-reportes-search:reportes-esg:anuncio","marca":"PS","tipo":"SEM","campana":"PS Argentina - SuSe - ESG / Reportes - Search","grupo":"Reportes ESG","sitio":null,"pagina":null,"titulo":"Ajustar el anuncio de Reportes ESG","detalle":"La campaña más sana. La gente escribe «indicadores gri», «estándares gri en español», «gri sectoriales», «csrd»: el anuncio dice «Reporte GRI» pero no «indicadores», «estándares» ni «sectoriales». En Materialidad: «matriz de materialidad», «doble materialidad».\n\nTítulos propuestos: Reportes de Sostenibilidad | Estándares GRI en Español | Indicadores GRI: Te Guiamos | GRI Sectoriales | CSRD y Doble Materialidad | Matriz de Materialidad | Consultoría ESG | Consultoría Peterson | Hablemos de Tu Reporte | Datos ESG Que Se Sostienen\n\nDescripciones propuestas: Co-desarrollamos tu reporte de sostenibilidad: estándares GRI, indicadores y materialidad. | Doble materialidad y CSRD con una hoja de ruta clara. Acompañamos todo el proceso. | Consultora ESG con equipo en Argentina y presencia en más de 35 países. | Hablemos de tu reporte: te decimos qué indicadores aplican y por dónde empezar.\n\nQuitar: Datos ESG · Impacto ESG · Plan ESG Empresa\n\ngri + número, «qué es» y «qué significa» siguen a negativo: son lectores del indicador, no clientes.","evidencia":{"gasto_ars":39483,"fuerza_actual":"GOOD","titulos_hoy":14,"titulos_propuestos":10},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"PS:SEM:ps-argentina-suse-huella-de-agua-search:gestion-agua:anuncio","marca":"PS","tipo":"SEM","campana":"PS Argentina - SuSe - Huella de agua - Search","grupo":"Gestion agua","sitio":null,"pagina":null,"titulo":"Reescribir el anuncio de Gestion agua","detalle":"El 100% del gasto reciente es tratamiento de efluentes: no hay título que lo arregle. Si la campaña sigue, el anuncio tiene que decir qué es la huella hídrica corporativa y nombrar ISO 14046.\n\nTítulos propuestos: Huella Hídrica Corporativa | Huella de Agua ISO 14046 | Medimos Tu Huella Hídrica | Riesgo Hídrico en Tu Cadena | Consultora Ambiental | Consultoría Peterson | Te Acompañamos a Medir | Hablemos de Tu Consumo\n\nDescripciones propuestas: Medimos con vos la huella hídrica de tu empresa y tu producto bajo ISO 14046. | Evaluamos riesgo hídrico en operaciones y cadena de valor. No tratamos efluentes: medimos. | Consultora ambiental con equipo en Argentina y presencia en más de 35 países.\n\nQuitar: Gestion Del Agua · Agua En Industria · Consumo De Agua · Agua Agroindustrial\n\nAntes: eliminar «gestion del agua industrial» y negativos tratamiento, efluentes, planta, calculadora.","evidencia":{"gasto_ars":12976,"fuerza_actual":"AVERAGE","titulos_hoy":14,"titulos_propuestos":8},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Propuestas de anuncios"},{"clave":"CU:SEO:espana-controlunion-com:titulo-y-snippet","marca":"CU","tipo":"SEO","campana":null,"grupo":null,"sitio":"espana.controlunion.com","pagina":null,"titulo":"Título y snippet: GRS (15","detalle":"GRS (15.968 impr., pos. 8,1, CTR 0,27%) y Welfair (11.232, pos. 8,3, 0,31%) están en primera página y nadie hace clic. Reescribir title y meta con la intención real: «Certificación GRS: requisitos, auditoría y cómo obtenerla».","evidencia":{"propiedad":"España"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Recomendaciones SEO para los sitios"},{"clave":"CU:SEO:espana-controlunion-com:iso-45001","marca":"CU","tipo":"SEO","campana":null,"grupo":null,"sitio":"espana.controlunion.com","pagina":null,"titulo":"ISO 45001: La mayor demanda del grupo (72","detalle":"La mayor demanda del grupo (72.363 impr., pos. 11,6) con página propia. Contenido de apoyo: requisitos, plazos, diferencias con OHSAS, preguntas frecuentes. Pasar de 11 a primera página vale más que cualquier campaña.","evidencia":{"propiedad":"España"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Recomendaciones SEO para los sitios"},{"clave":"CU:SEO:espana-controlunion-com:iscc","marca":"CU","tipo":"SEO","campana":null,"grupo":null,"sitio":"espana.controlunion.com","pagina":null,"titulo":"ISCC: Dos URL compiten (iscc-plus e iscc_eu) y la query «iscc» pasó de 605 a 11 impresiones desd","detalle":"Dos URL compiten (iscc-plus e iscc_eu) y la query «iscc» pasó de 605 a 11 impresiones desde España. Unificar en una página madre ISCC con secciones EU y PLUS, redirigir la otra.","evidencia":{"propiedad":"España"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Recomendaciones SEO para los sitios"},{"clave":"CU:SEO:espana-controlunion-com:versiones-en","marca":"CU","tipo":"SEO","campana":null,"grupo":null,"sitio":"espana.controlunion.com","pagina":null,"titulo":"Versiones EN: gmp+, gstc y bienestar animal reparten impresiones entre la URL en español y la /en/","detalle":"gmp+, gstc y bienestar animal reparten impresiones entre la URL en español y la /en/. Declarar hreflang y canonical por idioma para que España vea la versión en español.","evidencia":{"propiedad":"España"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Recomendaciones SEO para los sitios"},{"clave":"CU:SEO:espana-controlunion-com:iso-27001","marca":"CU","tipo":"SEO","campana":null,"grupo":null,"sitio":"espana.controlunion.com","pagina":null,"titulo":"ISO 27001: La página rankea en posición 43 para sus propias queries mientras la campaña paga ARS 6","detalle":"La página rankea en posición 43 para sus propias queries mientras la campaña paga ARS 6.019 por clic. Reescribir con vocabulario de búsqueda: certificación, precio, requisitos, plazos, auditoría.","evidencia":{"propiedad":"España"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Recomendaciones SEO para los sitios"},{"clave":"CU:SEO:portugal-controlunion-com:iso-9001","marca":"CU","tipo":"SEO","campana":null,"grupo":null,"sitio":"portugal.controlunion.com","pagina":null,"titulo":"ISO 9001: 1","detalle":"1.271 impr. en posición 12,3 y cayendo (1.174 → 85 entre tramos). Revisar la página: es la única de la unidad con caída fuerte.","evidencia":{"propiedad":"Portugal"},"prioridad":"alta","estado":"propuesta","mes_alta":"2026-09","origen":"Recomendaciones SEO para los sitios"},{"clave":"CU:SEO:portugal-controlunion-com:aquacultura","marca":"CU","tipo":"SEO","campana":null,"grupo":null,"sitio":"portugal.controlunion.com","pagina":null,"titulo":"Aquacultura: La página de industria /industry/aquacultura-e-pesca/ tiene 4","detalle":"La página de industria /industry/aquacultura-e-pesca/ tiene 4.959 impr. en posición 6,2 y CTR 0,06%: no responde a la búsqueda. Título con «certificação» y enlaces a ASC, MSC, BAP.","evidencia":{"propiedad":"Portugal"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Recomendaciones SEO para los sitios"},{"clave":"CU:SEO:portugal-controlunion-com:ocs-y-pefc","marca":"CU","tipo":"SEO","campana":null,"grupo":null,"sitio":"portugal.controlunion.com","pagina":null,"titulo":"OCS y PEFC: OCS reparte entre PT y /en/; PEFC está en 9,0 con 525 impr","detalle":"OCS reparte entre PT y /en/; PEFC está en 9,0 con 525 impr. Hreflang y refuerzo interno desde /industry/florestal/ a la página PEFC.","evidencia":{"propiedad":"Portugal"},"prioridad":"media","estado":"propuesta","mes_alta":"2026-09","origen":"Recomendaciones SEO para los sitios"}]'::jsonb) as x(clave text, marca text, tipo text, campana text, grupo text, sitio text, pagina text, titulo text, detalle text, evidencia jsonb, prioridad text, estado text, mes_alta text, origen text)
left join seo_sem.campanas c on c.nombre = x.campana left join seo_sem.grupos g on g.campana_id = c.id and g.nombre = x.grupo
on conflict (clave) do update set campana_id = excluded.campana_id, grupo_id = excluded.grupo_id, sitio = excluded.sitio, pagina = excluded.pagina, titulo = excluded.titulo, detalle = excluded.detalle, evidencia = excluded.evidencia, prioridad = excluded.prioridad, origen = excluded.origen;
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen)
