select x.fuente, x.corrida_en, x.desde, x.hasta, x.filas, x.detalle from jsonb_to_recordset('[{"fuente":"google_ads","corrida_en":"2026-09-29T18:18:22.453627+00:00","desde":"2026-09-01","hasta":"2026-09-27","filas":131,"detalle":{"ventana":"2026-09-01_2026-09-27","dias":27,"snapshot_estructura":"estructura_20260929"}},{"fuente":"search_console","corrida_en":"2026-09-16T15:41:14.584121+00:00","desde":"2025-05-04","hasta":"2026-09-14","filas":2345,"detalle":{"archivos":2,"cortes":"queries, pages, query_page, devices, daily, queries_agg, device_total, device_date"}}]'::jsonb) as x(fuente text, corrida_en timestamptz, desde date, hasta date, filas integer, detalle jsonb)
where not exists (select 1 from seo_sem.extracciones e where e.fuente = x.fuente and e.hasta = x.hasta);
